def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    nearest = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                nearest[i] = min(nearest[i], d / (a + b))
    total = sum(occ[i] for i in range(n) if isfinite(nearest[i]))
    return sum(occ[i] * nearest[i] for i in range(n) if isfinite(nearest[i])) / total if total > 0 else 0.0

