def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [x.get('element') for x in sites]
    radii = [(props.get(e) or {}).get('covalent_radius_A') for e in elements]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    counts = {}
    occupied = 0.0
    for i in range(n):
        if radii[i] is not None and radii[i] > 0:
            counts[elements[i]] = counts.get(elements[i], 0.0) + occ[i]
            occupied += occ[i]
    if occupied <= 0:
        return 0.0
    expected = 1.0 - sum((v / occupied) ** 2 for v in counts.values())
    if expected <= 1e-12:
        return 0.0
    unlike = 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.3 * (a + b):
                w = occ[i] * occ[j]
                total += w
                if elements[i] != elements[j]:
                    unlike += w
    return 1.0 - unlike / (total * expected) if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    first = [inf] * n
    second = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            if d < first[i]:
                second[i] = first[i]
                first[i] = d
            elif d < second[i]:
                second[i] = d
    value = 0.0
    total = 0.0
    for i in range(n):
        if first[i] > 0 and isfinite(second[i]):
            value += occ[i] * (second[i] / first[i] - 1.0)
            total += occ[i]
    return value / total if total > 0 else 0.0
